from collections import deque
def bfs(succ, depart):
    dist = {depart: 0}
    file = deque([depart])
    while file:
        u = file.popleft()
        for v in succ.get(u, ()):
            if v not in dist:
                dist[v] = dist[u] + 1
                file.append(v)
    return dist
